import { useMemo } from "react";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Layers } from "lucide-react";

type SourceRow = { category: string | null; enabled: boolean | null };
type ItemRow = { category: string | null };

export function CategoryCoveragePanel() {
  const { data, isLoading } = useQuery({
    queryKey: ["category-coverage-panel"],
    queryFn: async () => {
      const [sourcesRes, itemsRes] = await Promise.all([
        supabase.from("threat_sources").select("category,enabled").eq("enabled", true),
        supabase.from("threat_items").select("category").limit(5000).order("published_at", { ascending: false }),
      ]);
      if (sourcesRes.error) throw sourcesRes.error;
      if (itemsRes.error) throw itemsRes.error;
      return {
        sources: (sourcesRes.data || []) as SourceRow[],
        items: (itemsRes.data || []) as ItemRow[],
      };
    },
  });

  const stats = useMemo(() => {
    if (!data) return { rows: [], missing: [] as string[] };

    const sourceCount = new Map<string, number>();
    const itemCount = new Map<string, number>();

    for (const row of data.sources) {
      const c = (row.category || "uncategorized").trim();
      sourceCount.set(c, (sourceCount.get(c) || 0) + 1);
    }
    for (const row of data.items) {
      const c = (row.category || "uncategorized").trim();
      itemCount.set(c, (itemCount.get(c) || 0) + 1);
    }

    const categories = [...new Set([...sourceCount.keys(), ...itemCount.keys()])].sort();
    const rows = categories.map((category) => ({
      category,
      sourceCount: sourceCount.get(category) || 0,
      itemCount: itemCount.get(category) || 0,
      healthy: (sourceCount.get(category) || 0) > 0 && (itemCount.get(category) || 0) > 0,
    }));
    const missing = rows.filter((r) => r.sourceCount > 0 && r.itemCount === 0).map((r) => r.category);
    return { rows, missing };
  }, [data]);

  return (
    <Card className="mb-8 border-border/60 bg-card/60 backdrop-blur">
      <CardHeader className="pb-3">
        <CardTitle className="flex items-center gap-2 text-base">
          <Layers className="h-4 w-4 text-primary" />
          Category Data Coverage
        </CardTitle>
      </CardHeader>
      <CardContent>
        {isLoading ? (
          <div className="text-sm text-muted-foreground">Checking categories...</div>
        ) : (
          <div className="space-y-3">
            {stats.missing.length > 0 ? (
              <div className="rounded-md border border-warning/40 bg-warning/10 p-3 text-xs text-warning">
                Enabled source categories with no recent items: {stats.missing.join(", ")}
              </div>
            ) : (
              <div className="rounded-md border border-success/40 bg-success/10 p-3 text-xs text-success">
                All enabled source categories are receiving data.
              </div>
            )}
            <div className="grid gap-2 md:grid-cols-2 lg:grid-cols-3">
              {stats.rows.map((row) => (
                <div key={row.category} className="rounded-md border border-border/50 bg-muted/20 p-2">
                  <div className="mb-1 flex items-center justify-between gap-2">
                    <span className="truncate text-xs font-medium">{row.category}</span>
                    <Badge variant="outline" className={row.healthy ? "text-success border-success/40" : "text-warning border-warning/40"}>
                      {row.healthy ? "ok" : "check"}
                    </Badge>
                  </div>
                  <div className="text-[11px] text-muted-foreground">
                    Sources: {row.sourceCount} · Items: {row.itemCount}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}
